sys_script_include.script:
MSSTradeTaskAssignGrp = Class.create();
MSSTradeTaskAssignGrp.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getAssignmentGroups: function(taskT, shortDesc, _custodyT) {
        var taskShortDesc = gs.getProperty('x_hsb11_mss_c_proc.mss.custody.task.shortDesc');
        var tempSd = [];
        var custTemp = new GlideRecord("x_hsb11_mss_c_proc_custody_trade_task_template");
        custTemp.addEncodedQuery('template_id=CUSTODYTTMP00062^ORtemplate_id=CUSTODYTTMP00063'); //MSSCUSTODY1479
        custTemp.query();

        while (custTemp.next()) {
            tempSd.push(custTemp.template_short_description.toString());
        }
        if (taskT.toLowerCase() == 'maker' || taskT.toLowerCase() == 'checker' && ((shortDesc.toString() != taskShortDesc.toString()) && (shortDesc.toString() != tempSd[0]) && (shortDesc.toString() != tempSd[1]))) {
            var groups = this.getMatchingGroups(taskT, _custodyT);
            return groups;
        } else if (taskT.toLowerCase() == 'checker' && (shortDesc.toString() == taskShortDesc.toString()) || (shortDesc.toString() == tempSd[0]) || (shortDesc.toString() == tempSd[1])) {
            var managerGroups = this.checkerManagerGrp(_custodyT);
            return managerGroups;

        } else {
            var custodyGroups = this.getMatchingGroups(taskT, _custodyT);
            return custodyGroups;
        }
    },

    // MSSCUSTODY-7146 - New function created for assignment logic in custody task and bulk record where a GSC user will be able to assign task to market user and vice versa.
    // The function will show most relevant groups, based on the business and task type, are available for assignment. 
    // This function is be called in sys_dictionary_override for assignment_group field in reference qualifier
    getAssignmentGroupsForCustodyTaskAndBulk: function(taskT, shortDesc, _custodyT, tableName) {
        try {
            var taskType = taskT.toLowerCase();
            var owningBusiness = '';
            if (tableName == 'x_hsb11_mss_c_proc_mss_custody_task') {
                owningBusiness = _custodyT.trade_id.owning_business.toString();
            } else if (tableName == 'x_hsb11_hsbc_mss_o_hsbc_bulk_transaction') {
                owningBusiness = _custodyT.toString();
            }
            var gr = new GlideRecord("sys_user_group_type");
            gr.addEncodedQuery('nameSTARTSWITH' + owningBusiness);
            gr.query();
            if (gr.next()) {
                var type = gr.sys_id;
                var query = 'typeLIKE' + type + '^u_group_locationINOnshore,GSC^nameLIKE' + taskType;
            }
            return query;
        } catch (ex) {
            gs.info('No valid groups');
        }
    },


    getMatchingGroups: function(taskT, _custodyT) {

        var outcomesArray = [];
        var owningBusiness = _custodyT.trade_id.owning_business.toString().split(' '); // Story 3308

        var userGroup = gs.getUser().getMyGroups(); // Story 3308
        /*var groupQ = 'parent.nameSTARTSWITHiQube-Custody-HBAP^parent.nameLIKE' + taskT + '^typeLIKE2269529d1b844650ff37eb14b24bcb19^nameLIKEGSC^ORnameLIKE' + owningBusiness[1] + ' ' + owningBusiness[0];*/
        var groupQ = 'typeLIKE' + owningBusiness + '^u_group_locationINOnshore,GSC^nameLIKE' + taskT;
        var group = new GlideRecord('sys_user_group');
        group.addEncodedQuery(groupQ);
        group.addQuery('sys_id', 'IN', userGroup); // Story 3308
        //group.addQuery('name', 'NOT LIKE,','Infodir-');
        group.query();

        while (group.next()) {

            outcomesArray.push(group.sys_id.toString());
        }


        return 'sys_idIN' + outcomesArray;
    },


    checkerManagerGrp: function(_custodyT) {
        var outcomesArray = [];
        var userGroup = gs.getUser().getMyGroups();
        var owningBusiness = _custodyT.trade_id.owning_business.toString().split(' '); // Story 3308
        // var groupQ = 'parent.nameSTARTSWITHiQube-Custody-HBAP^parent.nameLIKE' + taskT + '^typeLIKE2269529d1b844650ff37eb14b24bcb19^nameLIKEGSC^ORnameLIKE' + owningBusiness[1] + ' ' + owningBusiness[0];

        //var query = "parent.nameSTARTSWITHiQube-Custody-HBAP^parent.nameLIKEchecker^ORparentLIKEmanager";
        var groupQ = 'parent.nameSTARTSWITHiQube-Custody-HBAP^parent.nameLIKEchecker^ORparentLIKEmanager^typeLIKE2269529d1b844650ff37eb14b24bcb19^nameLIKEGSC^ORnameLIKE' + owningBusiness[1] + ' ' + owningBusiness[0]; // Story 3308
        var mgrGroup = new GlideRecord('sys_user_group');
        group.addEncodedQuery(groupQ); // Story 3308
        mgrGroup.addQuery('sys_id', 'IN', userGroup); // Story 3308
        mgrGroup.addEncodedQuery(groupQ); // Story 3308
        mgrGroup.query();

        while (mgrGroup.next()) {
            outcomesArray.push(mgrGroup.sys_id.toString());
        }
        return 'sys_idIN' + outcomesArray;
    },

    type: 'MSSTradeTaskAssignGrp'
});
